 import React, { useState, useEffect } from 'react'
import { useParams, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import FollowButton from '../components/follow/FollowButton'
import VerifiedBadge from '../components/VerifiedBadge'

export default function Followers() {
    const { userId, type } = useParams()
    const { user } = useAuth()
    const [users, setUsers] = useState([])
    const [loading, setLoading] = useState(true)
    const [profile, setProfile] = useState(null)

    useEffect(() => {
        loadData()
    }, [userId, type])

    const loadData = async () => {
        setLoading(true)
        try {
            // Get user profile
            const { data: profileData } = await supabase
                .from('profiles')
                .select('id, username, full_name, avatar_url, is_verified')
                .eq('id', userId)
                .single()
            setProfile(profileData)

            // Get followers or following
            let query
            if (type === 'followers') {
                query = supabase
                    .from('followers')
                    .select(`
                        follower_id,
                        profiles:follower_id (id, username, full_name, avatar_url, is_verified)
                    `)
                    .eq('following_id', userId)
            } else {
                query = supabase
                    .from('followers')
                    .select(`
                        following_id,
                        profiles:following_id (id, username, full_name, avatar_url, is_verified)
                    `)
                    .eq('follower_id', userId)
            }

            const { data } = await query
            const userList = data?.map(item => 
                type === 'followers' ? item.profiles : item.profiles
            ) || []
            
            setUsers(userList)
        } catch (error) {
            console.error('Error loading followers:', error)
        } finally {
            setLoading(false)
        }
    }

    if (loading) {
        return <div className="text-center py-12">Loading...</div>
    }

    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-center gap-3">
                    <Link to={`/profile/${userId}`} className="text-2xl hover:opacity-80">←</Link>
                    <div>
                        <h1 className="text-2xl font-bold text-gray-800">
                            {type === 'followers' ? '👥 Followers' : '👤 Following'}
                        </h1>
                        <p className="text-gray-500">@{profile?.username}</p>
                    </div>
                </div>
            </div>

            {users.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">👀</div>
                    <p className="text-gray-500">
                        {type === 'followers' 
                            ? 'No followers yet' 
                            : 'Not following anyone yet'}
                    </p>
                </div>
            ) : (
                <div className="space-y-2">
                    {users.map((u) => (
                        <div key={u.id} className="bg-white rounded-xl shadow-md p-4 flex items-center justify-between">
                            <Link to={`/profile/${u.id}`} className="flex items-center gap-3 hover:opacity-80 flex-1">
                                <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                                    {u.username?.[0]?.toUpperCase() || 'U'}
                                </div>
                                <div>
                                    <div className="font-semibold flex items-center gap-1.5">
                                        {u.full_name || u.username}
                                        {u.is_verified && <VerifiedBadge size="sm" />}
                                    </div>
                                    <div className="text-sm text-gray-500">@{u.username}</div>
                                </div>
                            </Link>
                            {u.id !== user?.id && (
                                <FollowButton 
                                    userId={u.id} 
                                    username={u.username}
                                    onFollowChange={loadData}
                                />
                            )}
                        </div>
                    ))}
                </div>
            )}
        </div>
    )
}
